#include <iostream>
#include <string>
using namespace std;

int main() {
    const int MAX_PLAYERS = 4;        // UPPER_SNAKE_CASE: a constant
    int playerScore = 0;              // camelCase: a variable
    const auto START_SPEED = 2.5;     // const and auto work together

    string label = to_string(playerScore);   // a standard library name

    cout << label << " / " << MAX_PLAYERS << " at speed " << START_SPEED << endl;
    return 0;
}

